def landscape(city='Tokyo', tone='#c3d5ca'):
    return f'''<div class="landscape"><svg viewBox="0 0 500 200" preserveAspectRatio="xMidYMid slice"><rect width="500" height="200" fill="{tone}"/><circle cx="390" cy="60" r="28" fill="#f7e7c8"/><path d="M0 160L120 75L210 132L320 65L500 155V200H0Z" fill="#91aaa4"/><path d="M0 175L70 143L190 177L300 132L430 160L500 124V200H0Z" fill="#6f8c87"/><path d="M0 198Q180 173 500 186" fill="none" stroke="#dfe9df" stroke-width="8"/></svg><span class="loc">{city}</span></div>'''

def map_preview():
    return '''<div class="map"><svg viewBox="0 0 340 180" preserveAspectRatio="none"><rect width="340" height="180" fill="#eef0e9"/><path d="M245 -20Q160 100 230 210" stroke="#b9ddeb" stroke-width="27" fill="none"/><rect x="24" y="22" width="74" height="50" rx="10" fill="#d7e5cf"/><rect x="255" y="86" width="64" height="73" rx="10" fill="#d7e5cf"/><g stroke="white" stroke-width="9"><path d="M0 50L340 130M70 0L120 180M0 140L340 25M290 0L285 180"/></g><g stroke="#d6d9d2" stroke-width="1"><path d="M0 50L340 130M70 0L120 180M0 140L340 25"/></g></svg><span class="maptop">Google Maps area · English labels</span><span class="pin">2</span><span class="mapfoot">Schematic placeholder — production uses a real Google map</span></div>'''

def rail():
    return '<aside class="rail"><b class="brand">⌁</b><b>⌂</b><b class="on">▣</b><b>♧</b><b>⌕</b><b style="margin-top:auto;font-size:13px;background:#163555;color:white;border-radius:50%;width:30px;height:30px">A</b></aside>'

def app(content):
    return '<div class="app">'+rail()+'<main class="content">'+content+'</main></div>'

def main_header(active='Overview'):
    return '<div class="top compact-top"><div class="row"><h2>My trips</h2><div class="switches"><span class="'+('active' if active=='Overview' else '')+'">Overview</span><span class="'+('active' if active=='All trips' else '')+'">All trips <b class="count">9</b></span></div></div><button class="blue">＋ Create trip</button></div>'

def trip_header():
    return '<div class="top"><div class="row"><span class="small">‹ My trips</span><h2 class="tripname">Tokyo, one day at a time</h2><span class="small">19–22 Sep</span></div><button>Share</button></div><div class="switches"><span class="active">Itinerary</span><span>Map</span><span>Places</span><span>Trip details</span><span style="margin-left:auto;font-size:12px">Saves ↗</span></div>'

def dayrail():
    return '<nav class="days">'+''.join(f'<div class="day {"active" if i==2 else ""}"><strong>Day {i}</strong><span>{18+i} September</span></div>' for i in range(1,5))+'</nav>'

def stop(name,time,meta,kind='',active=False,number=1,edit=False,locked=False):
    controls = ('<div class="locked">▣ Fixed booking · time stays put</div>' if locked else '<div class="move-actions"><button>↑</button><button>↓</button><button>Move to day ▾</button><button style="margin-left:auto;color:#aa4e45">Remove</button></div>') if edit else ''
    return f'<div class="stop {"active" if active else ""}"><div class="thumb {kind}">{"♧" if kind=="park" else "◒" if kind=="food" else "⌂"}</div><div class="grow"><div class="time">{time}</div><h4>{name}</h4><small>{meta}</small>{controls}</div>'+('' if edit else f'<span class="number">{number}</span>')+'</div>'

def stops(edit=False):
    return stop('Garden walk','09:00 – 10:00','Sample stop · Garden', 'park',number=1,edit=edit)+('<div class="travel">≈ 15 min by transit · estimate</div>' if not edit else '')+stop('Little Lantern Cafe','10:15 – 11:00','Sample stop · Cafe','food',active=not edit,number=2,edit=edit)+('<div class="travel">≈ 10 min walk · estimate</div>' if not edit else '')+stop('Studio ceramics','11:10 – 12:10','Hours unknown · check before visiting','',number=3,edit=edit)+'<div class="break">12:10 – 13:00 &nbsp; Lunch break</div>'+stop('Dinner reservation','19:30 – 21:00','▣ Fixed booking','food',number=4,edit=edit,locked=True)

pages=[]

def page(num,title,sub,content,notes):
    pages.append(f'<section class="board" data-document-role="page" data-label="{num} — {html.escape(title)}"><div class="board-head"><div><h1>{title}</h1><p>{sub}</p></div><span class="num">MY TRIP / {num}</span></div>{content}<div class="notes">{notes}</div><span class="concept">PROPOSED UX · 20 SEP 2026 · Synthetic names, dates and hours for layout only · Not a live application or usability result</span></section>')

cards=''
for city,title,date,status,cta,color in [('Kyoto','Kyoto, at our own pace','10–14 Oct · 5 days','In planning','Continue planning','#d6d9bd'),('Seoul','A weekend in Seoul','23–26 Oct · 4 days','Itinerary saved','View itinerary','#c8d9e7'),('Taipei','Taipei after dark','1–4 Nov · 4 days','In planning','Continue planning','#dfccbd')]:
    cards+=f'<article class="tripcard">{landscape(city,color)}<div class="body"><span class="tag">{status}</span><h4>{title}</h4><span class="small">{date}</span><div class="action">{cta}<span>→</span></div></div></article>'
content=main_header()+f'<section class="current">{landscape()}<div class="current-info"><div class="row between"><span class="tag green">Happening now</span><span class="small">Day 2 of 4</span></div><h3>Tokyo, one day at a time</h3><span class="small">19–22 September · Tokyo</span><div class="row bottom"><button class="blue">Open today</button><button>View map</button><span class="small" style="margin-left:auto">Trip details →</span></div></div></section><div class="section-title"><h3>Upcoming <span class="small">3</span></h3><span class="small">Nearest departure first</span></div><div class="cards">{cards}</div>'
page('01','My Trips · compact and purposeful','One title. Two visible views. Your trips begin immediately.',app(content),'<span><strong>01</strong> Remove the journal label, slogan and decorative punctuation.</span><span><strong>02</strong> All trips becomes a persistent, full-size view tab.</span>')

panel='<aside class="panel"><div class="row between small"><span>Selected place · Stop 2</span><span>✕</span></div><h3><a href="#">Little Lantern Cafe ↗</a></h3><div class="hours">◷ Sunday hours · 09:00–18:00</div><div class="small" style="margin-top:4px">Open during your 10:15–11:00 visit</div><div class="detail-actions"><button class="blue">Full details →</button><button>＋ Note</button></div><div class="small" style="margin-bottom:10px">Cafe · Sample district</div>'+map_preview()+'<div class="minilink">Get directions ↗</div><div class="source">Saved from your video · View source →</div><p>Hours shown for the planned day. If unavailable, this line says “Hours unknown”.</p></aside>'
content=trip_header()+'<div class="workspace">'+dayrail()+'<section><div class="day-head"><h3>Day 2 <span class="small">Sun, 20 Sep</span></h3><button class="blue">✎ Edit day</button></div><div class="checkline">◷ 1 place has unknown hours · Review</div>'+stops()+'</section>'+panel+'</div>'
page('02','Trip workspace · actions at the point of need','The day owns its edit action. The selected place answers the next question.',app(content),'<span><strong>03</strong> Edit day sits beside the day heading, above the stops.</span><span><strong>04</strong> Title opens Google Maps; hours and Full details stay above the map.</span>')

pool='<aside class="panel"><div class="row between"><strong>Add to Day 2</strong><span class="tag">2 available</span></div><p>Confirmed places not on your itinerary.</p><div class="pool"><div class="row between"><strong>Riverside gallery</strong><button>＋ Add</button></div><span class="small">Sample confirmed place</span></div><div class="pool"><div class="row between"><strong>Paper craft studio</strong><button>＋ Add</button></div><span class="small">Hours unknown</span></div><div class="rejection"><strong>Example: move not saved</strong><br>The new order would make your fixed dinner unreachable. Your last saved plan is unchanged.</div><div class="warning-card">Proposed behavior: each move saves only after validation. Saving and failure messages stay beside the edited day.</div></aside>'
content=trip_header()+'<div class="workspace edit">'+dayrail()+'<section><div class="day-head"><h3>Editing Day 2</h3><div class="row"><button>Undo</button><button class="blue">Done</button></div></div><div class="edit-notice">Moves save as you go. Fixed bookings stay put.</div>'+stops(edit=True)+'<div class="statusbar"><span>✓ Saved</span><span>Last move can be undone</span></div></section>'+pool+'</div>'
page('03','Edit mode · visible, predictable, recoverable','Explicit move controls, a stable Done button, and feedback near the change.',app(content),'<span><strong>05</strong> No drag handle unless dragging actually works.</span><span><strong>06</strong> Locked bookings, failed moves and Undo remain obvious.</span>')

