data=[('Tokyo, one day at a time','Tokyo','19–22 Sep 2026','Happening now','green','Open'),('Kyoto, at our own pace','Kyoto','10–14 Oct 2026','In planning','','Plan'),('A weekend in Seoul','Seoul','23–26 Oct 2026','Itinerary saved','','Open'),('Taipei after dark','Taipei','1–4 Nov 2026','In planning','','Plan'),('Summer by the coast','Sample coast','8–11 Jun 2026','Past','','Open'),('A spring city break','Sample city','12–15 Apr 2026','Past','','Open')]
for title,city,date,status,tone,action in data:
    rows+=f'<div class="trow"><div class="name"><span class="miniart">⌁</span><span><strong>{title}</strong><small>{city}</small></span></div><span>{date}</span><span><span class="tag {tone}">{status}</span></span><span class="muted">{5 if city == "Kyoto" else 4} days</span><span class="open">{action} →</span></div>'
content=main_header('All trips')+'<div class="filters"><button class="chosen">All 9</button><button>Current 1</button><button>Upcoming 4</button><button>Past 4</button><div class="search">⌕ Search trip or destination</div><button>Departure date ▾</button></div><div class="table"><div class="thead"><span>TRIP</span><span>DATES</span><span>STATUS</span><span>DURATION</span><span></span></div>'+rows+'</div><div class="row between" style="margin-top:16px"><span class="small">Showing 6 of 9 · example layout</span><button>Show more</button></div>'
page('04','All Trips · a useful list, not another introduction','Same compact header and tabs. Search and filters live directly above the trips.',app(content),'<span><strong>07</strong> Remove the stacked back link, Every trip heading and historical sentence.</span><span><strong>08</strong> Upcoming includes future drafts; planning status is a separate fact.</span>')

phone1='<div class="phone"><div class="status"><span>9:41</span><span>▰ ▰</span></div><div class="inner"><div class="top"><h2>‹ Tokyo trip</h2><span class="small">Share</span></div><div class="row small"><strong style="color:#216bd9">Itinerary</strong><span>Map</span><span>Places</span><span>Details</span></div><div class="daytabs"><span>Day 1</span><span class="on">Day 2</span><span>Day 3</span><span>Day 4</span></div><div class="day-head"><h3>Sun, 20 Sep</h3><button class="blue">✎ Edit day</button></div><div class="checkline">1 place has unknown hours</div>'+stop('Garden walk','09:00–10:00','Garden · Sample stop','park',number=1)+'<div class="travel">≈ 15 min transit</div>'+stop('Little Lantern Cafe','10:15–11:00','Cafe · Sample stop','food',active=True,number=2)+'<div class="travel">≈ 10 min walk</div>'+stop('Studio ceramics','11:10–12:10','Hours unknown','',number=3)+'<div class="break">12:10–13:00 · Lunch break</div></div><div class="bottomnav"><span>Home</span><strong style="color:#216bd9">My trips</strong><span>Inspiration</span></div></div>'
phone2='<div class="phone"><div class="status"><span>9:41</span><span>▰ ▰</span></div><div class="inner"><div class="top"><h2>‹ Tokyo trip</h2><span class="small">Share</span></div><div class="row small">Itinerary &nbsp; Map &nbsp; Places &nbsp; Details</div></div><div class="shade"></div><div class="sheet"><div class="handle"></div><div class="row between small"><span>Stop 2 · 10:15–11:00</span><button class="textbtn" style="padding:3px;min-height:28px">Close ✕</button></div><h3>Little Lantern Cafe ↗</h3><div class="hours">Sunday hours · 09:00–18:00</div><div class="small" style="margin-top:4px">Open during your planned visit</div><div class="detail-actions"><button class="blue">Full details →</button><button>＋ Note</button></div><div class="small" style="margin:0 0 10px">Cafe · Sample district</div>'+map_preview()+'<p style="font-size:12px;color:#216bd9;font-weight:bold">Get directions ↗</p><p style="font-size:11px;color:#64738a;border-top:1px solid #e3e9f1;padding-top:13px">Saved from your video · View source →</p></div></div>'
notes='<div class="mobile-notes"><h3>Selection should feel immediate.</h3><div class="item"><strong>Open details where the user is</strong><p>Selecting a stop opens a bottom sheet. No scrolling past the entire day to find a changed panel.</p></div><div class="item"><strong>Keep the useful actions in view</strong><p>Place title, hours and Full details fit above the map. Close restores focus and the itinerary scroll position.</p></div><div class="item"><strong>Preserve information on phones</strong><p>All Trips rows retain dates and status. Use a two-line row instead of hiding those fields.</p></div><div class="rule"><strong>Motion rule</strong><br>Short 160–200ms sheet and selection transitions. No repeated card entrances. Respect reduced motion.</div><div class="warning-card"><strong>Unknown stays unknown</strong><br>“Hours unknown · Check on Google Maps” replaces invented hours. Unmatched places never link to a guessed branch.</div></div>'
page('05','Mobile · visible response, fewer trips up and down the page','A focused place sheet replaces a panel that falls below the itinerary.', '<div class="phones">'+phone1+phone2+notes+'</div>','<span><strong>09</strong> Day controls stay in reach.</span><span><strong>10</strong> A dialog sheet keeps place details and the return path together.</span>')

